INSERT INTO "ai_compliance_checklists" VALUES('b6113743ae214fda8fd5896d08d429ea','4a6f596cdcef437cbfa1c777e0db5e6c','{"B_i": {"answer": "Yes", "remarks": "Contains personal financial transaction data classified as sensitive under UU PDP."}, "B_v": {"answer": "Yes", "remarks": "Research consent included in digital banking app consent form signed by customers."}, "D_i": {"answer": "Yes", "remarks": "Generative AI models are used for customer financial insight generation. AI Checklist Assessment completed separately."}, "B_ii": {"answer": "Yes", "remarks": "PII fields are masked and tokenised before sharing; access restricted to authorised team members only."}, "B_iv": {"answer": "Yes", "remarks": "Customer consent obtained via Terms & Conditions agreement at account opening."}, "B_vi": {"answer": "Yes", "remarks": "Data is processed within the BU secured analytics environment with role-based access control enforced."}, "A_i_1": {"answer": "No", "remarks": "No revenue cannibalization risk; data is used solely for internal AI model development."}, "A_i_2": {"answer": "No", "remarks": "Data is anonymised prior to use; no direct customer relationship impact."}, "A_i_3": {"answer": "No", "remarks": "No other commercial interests identified."}, "B_iii": {"answer": "Yes", "remarks": "Transaction records contain customer identifiers and financial data constituting personal data."}, "C_i_1": {"answer": "No", "remarks": "Compliant with OJK regulations on data usage for financial analytics purposes."}, "C_i_2": {"answer": "No", "remarks": "Compliant with UU PDP (Personal Data Protection Law No. 27/2022)."}, "C_i_3": {"answer": "No", "remarks": "Compliant with internal Data Governance Policy v2.1 and AI Ethics Guidelines."}, "A_ii_1": {"answer": "No", "remarks": "No confidential partnership data is included in the transaction dataset."}, "A_ii_2": {"answer": "No", "remarks": "No patent information present in scope of data."}, "A_ii_3": {"answer": "No", "remarks": "No M&A-related information included."}, "A_ii_4": {"answer": "No", "remarks": "No other commercial secrets identified in the dataset."}, "sign_off": {"remarks": "All compliance requirements have been reviewed and satisfied. Data sharing approved for AI model development purposes.", "approved": "Yes", "prepared_by": "Rendra Kusuma Wijaya", "prepared_date": "2026-01-25", "acknowledged_by": "Dewi Rahayu", "acknowledged_date": "2026-01-25", "prepared_position": "Head of Digital Innovation", "prepared_signature": "data:image/png;base64,", "acknowledged_position": "Senior Data Scientist", "acknowledged_signature": "data:image/png;base64,"}, "ai_assessment": {"items": {"input_1": {"status": "Yes", "remarks": "Customer transaction data is fully anonymised and tokenised before being used as AI model input. No raw PII \u2014 names, account numbers, phone numbers \u2014 is included in any prompt or model input."}, "input_2": {"status": "Yes", "remarks": "All data inputs to the Gen AI pipeline are pseudonymised. Customer identifiers are replaced with internal tokens, and synthetic dummy data is used during model exploration and testing phases."}, "input_3": {"status": "Yes", "remarks": "All prompts are reviewed by the AI Engineer and Data Scientist before use. Prompt templates are documented in the project repository under /docs/prompt-log.txt and versioned accordingly."}, "output_1": {"status": "Yes", "remarks": "All AI-generated financial insights are reviewed and validated by the Subject Matter Expert (Dewi Rahayu) before being surfaced to end users. A validation checklist is applied to each output batch to check for hallucinations, bias, or inaccuracies."}, "output_2": {"status": "Yes", "remarks": "Any source code generated or assisted by Gen AI undergoes mandatory peer review by a senior developer, security static analysis scanning, and functional testing before integration into the customer analytics platform."}, "before_use_1": {"status": "Yes", "remarks": "The platform has been reviewed against OJK regulations, UU PDP No. 27/2022, and internal AI Ethics & Governance Policy. Legal and compliance sign-off obtained prior to project initiation."}, "before_use_2": {"status": "Yes", "remarks": "The generative AI platform used for financial insight generation is officially licensed and has received formal written approval from the Chief Technology Officer and Head of Digital Innovation."}, "before_use_3": {"status": "Yes", "remarks": "Platform settings have been configured to disable interaction history logging. The team has opted out of all model training data-sharing options provided by the Gen AI service provider."}, "utilization_1": {"status": "Yes", "remarks": "AI-generated insights and recommendations are only released after independent assessment and sign-off by the authorised SME. A review checklist is used to confirm outputs are ready for customer-facing use."}, "utilization_2": {"status": "Yes", "remarks": "A feedback and correction loop is in place. Inaccurate or inappropriate AI outputs are flagged, corrected, and logged in the incident register before any distribution to customers or stakeholders."}}, "sign_off": {"approved": "Yes", "prepared_by": "Ahmad Fauzi", "prepared_date": "2026-01-27", "acknowledged_by": "Dewi Rahayu", "acknowledged_date": "2026-01-27", "prepared_position": "Senior Delivery Manager", "prepared_signature": "data:image/png;base64,", "acknowledged_position": "Senior Data Scientist", "acknowledged_signature": "data:image/png;base64,"}}}','draft',NULL,'2026-01-27 14:00:00');
INSERT INTO "ai_compliance_checklists" VALUES('ae5892cf97694a968185c2987d1809c7','5f8cf7466035447a9cfa3694bd423aaa','{"B_i": {"answer": "Yes", "remarks": "Dataset includes customer financial behaviour and transaction history, classified as sensitive personal financial data under UU PDP."}, "B_v": {"answer": "Yes", "remarks": "Customer consent for AI/ML model development is covered under the digital banking service agreement signed at account opening."}, "D_i": {"answer": "Yes", "remarks": "The credit risk scoring model utilises gradient boosting machine learning algorithms to predict default probability based on customer transaction patterns and financial behaviour data."}, "B_ii": {"answer": "Yes", "remarks": "Data is pseudonymized and aggregated prior to sharing. PII fields are masked and access is restricted to the authorized analytics team only."}, "B_iv": {"answer": "Yes", "remarks": "Written consent has been obtained through customer onboarding agreements and terms of service covering data use in credit risk assessment."}, "B_vi": {"answer": "Yes", "remarks": "All data processing is conducted within PT Finansial Nusantara''s secured analytics environment with role-based access controls and audit logging."}, "A_i_1": {"answer": "No", "remarks": "Credit risk data is used for internal analytics only; no revenue cannibalization risk identified."}, "A_i_2": {"answer": "No", "remarks": "Data is pseudonymized before sharing; customer identity is protected throughout the process."}, "A_i_3": {"answer": "No", "remarks": "No other commercial interest risks have been identified for this data sharing request."}, "B_iii": {"answer": "Yes", "remarks": "Transaction records and credit history contain personal financial data subject to the Personal Data Protection Law (UU PDP No. 27/2022)."}, "C_i_1": {"answer": "No", "remarks": "OJK regulations on credit scoring and data sharing have been reviewed; this request complies with applicable banking sector regulations."}, "C_i_2": {"answer": "No", "remarks": "Data sharing is compliant with UU PDP No. 27 of 2022; appropriate technical and organisational safeguards are in place."}, "C_i_3": {"answer": "No", "remarks": "Internal data governance policy and data sharing SOP have been reviewed; this request is fully compliant with internal regulations."}, "A_ii_1": {"answer": "No", "remarks": "No highly confidential partnership information is included in the requested dataset."}, "A_ii_2": {"answer": "No", "remarks": "Dataset contains transactional and behavioural data only; no patent-related information involved."}, "A_ii_3": {"answer": "No", "remarks": "No merger or acquisition information is included in the scope of this data sharing."}, "A_ii_4": {"answer": "No", "remarks": "No other commercial secrets identified within the requested credit data dataset."}, "sign_off": {"remarks": "All data governance requirements have been reviewed and verified. This data sharing is approved for credit risk model development purposes only.", "approved": "Yes", "prepared_by": "Dian Pratiwi", "prepared_date": "", "acknowledged_by": "Dewi Rahayu", "acknowledged_date": "", "prepared_position": "Head of Analytics", "prepared_signature": "", "acknowledged_position": "Senior Data Scientist", "acknowledged_signature": ""}}','draft',NULL,NULL);
INSERT INTO "ai_compliance_checklists" VALUES('1b7514994ac7434ba48d8cd0c88a7d66','724230d437c04791a8982cdda92c1f8a','{}','draft',NULL,NULL);
INSERT INTO "ai_compliance_checklists" VALUES('6ae7c72b400c4d30b87de35878cd8180','062b7358ccfe4b4ebbc603c7f4a92c9f','{"B_i": {"answer": "Yes", "remarks": "Dataset may contain customer and operational information classified as sensitive."}, "B_v": {"answer": "Yes", "remarks": "Consent for analytics and AI/ML use is obtained through service agreements and internal approvals."}, "D_i": {"answer": "Yes", "remarks": "Data may be used for AI/ML-based analytics such as forecasting, prediction, and operational optimization."}, "B_ii": {"answer": "Yes", "remarks": "Data is pseudonymized/masked and access is restricted to authorized personnel only."}, "B_iv": {"answer": "Yes", "remarks": "Written consent is covered under customer agreements and privacy notices."}, "B_vi": {"answer": "Yes", "remarks": "All data processing is conducted within secured environments with limited, role-based access and audit logging."}, "A_i_1": {"answer": "No", "remarks": "No revenue cannibalization risk; data is used for internal integration and reporting purposes only."}, "A_i_2": {"answer": "No", "remarks": "Customer data is handled under internal data protection policies; customer relationship risk is mitigated."}, "A_i_3": {"answer": "No", "remarks": "No other commercial interest risks have been identified for this data sharing request."}, "B_iii": {"answer": "Yes", "remarks": "Dataset contains personal data elements under UU PDP No. 27 Tahun 2022."}, "C_i_1": {"answer": "No", "remarks": "No violations of automotive industry regulations or compliance requirements identified."}, "C_i_2": {"answer": "No", "remarks": "Compliant with UU PDP No. 27 Tahun 2022 and applicable data protection regulations."}, "C_i_3": {"answer": "No", "remarks": "Compliant with internal data governance policies, SOPs, and enterprise security standards."}, "A_ii_1": {"answer": "No", "remarks": "The dataset does not contain confidential partnership or strategic collaboration information."}, "A_ii_2": {"answer": "No", "remarks": "No patent, intellectual property, or proprietary technical information is included."}, "A_ii_3": {"answer": "No", "remarks": "No merger, acquisition, or corporate restructuring information is included."}, "A_ii_4": {"answer": "No", "remarks": "No other commercial secrets have been identified within the requested dataset."}, "sign_off": {"remarks": "Data sharing for PRJ-2026-018 (Enterprise Data Integration Platform Implementation) is intended to support enterprise reporting, operational monitoring, and analytics across authorized Astra business units. The shared datasets include operational and transactional data from after sales, service, inventory, billing, and related systems. All sensitive and personal data are protected through pseudonymization, access control, and encryption. The activity complies with applicable laws and internal governance policies, and any AI/ML usage is limited to internal analytics and business improvement purposes.", "approved": "Yes", "prepared_by": "Bambang Budi Santoso", "acknowledged_by": "Adi Kurniawan", "prepared_position": "Head of IT Dept Head", "acknowledged_position": "Data Analyst"}, "ai_assessment": {"items": {"input_1": {"status": "No", "remarks": "Dataset contains personal and sensitive operational data; mitigated using pseudonymization"}, "input_2": {"status": "Yes", "remarks": "Sensitive data is pseudonymized before being processed by AI models"}, "input_3": {"status": "Yes", "remarks": "Prompts are standardized, documented, and reviewed for compliance"}, "output_1": {"status": "Yes", "remarks": "Outputs are validated by BI team using reporting systems and trusted datasets"}, "output_2": {"status": "Yes", "remarks": "All generated scripts are reviewed and tested before deployment"}, "before_use_1": {"status": "Yes", "remarks": "Fully compliant with applicable regulations; AI usage limited to internal analytics purposes"}, "before_use_2": {"status": "Yes", "remarks": "AI tools are enterprise-approved and comply with IT security standards"}, "before_use_3": {"status": "Yes", "remarks": "All configurations set to prevent data retention and training usage"}, "utilization_1": {"status": "Yes", "remarks": "Outputs require BI team validation and data owner approval before use"}, "utilization_2": {"status": "Yes", "remarks": "Outputs are corrected and revalidated before distribution"}}, "sign_off": {"approved": "Yes", "prepared_by": "Agus Setiawan", "acknowledged_by": "Adi Kurniawan", "prepared_position": "Senior Data Engineer", "acknowledged_position": "Data Analyst"}}}','draft',NULL,NULL);
INSERT INTO "ai_compliance_checklists" VALUES('c00eb3b1ae034db2b0a9818b10047d67','f3969df6dc194bc5812177071ec8d76e','{"sign_off": {"approved": "Yes", "acknowledged_by": "Dewi Rahayu", "acknowledged_position": "Head of Business Analytics", "prepared_by": "Sri Handayani", "prepared_position": "Head of CRM Department", "remarks": "Approved with conditions: (1) share only the pseudonymised feature table (hashed customer_id, no name, NIK, e-mail, phone or birth date); (2) vendor works only inside the BU analytics workspace, 4 named accounts, no download; (3) access ends 2027-03-31, then the data is deleted and a BAPD extermination record is created; (4) AICK and model fairness review must be completed before go-live. Ref: DPIA for PRJ-2026-022, DPA-2026-014 (dummy)."}, "A_i_1": {"answer": "No", "remarks": "Features are used only to build our own churn model; the vendor may not sell or reuse the data or the model."}, "A_i_2": {"answer": "No", "remarks": "Only pseudonymised features are shared; customers are not contacted by the vendor. Retention offers stay with our CRM team."}, "A_i_3": {"answer": "No", "remarks": "No pricing, margin or supplier terms in the dataset."}, "A_ii_1": {"answer": "No", "remarks": "Dataset holds customer behaviour features only; no partner or contract data."}, "A_ii_2": {"answer": "No", "remarks": "No product design or patent information included."}, "A_ii_3": {"answer": "No", "remarks": "Not related to any merger or acquisition."}, "A_ii_4": {"answer": "No", "remarks": "Store-level revenue and strategy are not included; spend is per customer and pseudonymised."}, "B_i": {"answer": "No", "remarks": "No religion, health, physical/mental condition, sexual life or bank/credit data. Features: tenure, monthly spend, visits, complaints, churn flag/score."}, "B_ii": {"answer": "Yes", "remarks": "customer_id is replaced by a hashed key; name, NIK, e-mail, phone and birth date are removed before sharing; the key table stays with the Data Owner."}, "B_iii": {"answer": "Yes", "remarks": "Pseudonymised data is still personal data under UU No. 27/2022 (PDP) because the BU can re-link it with the key table."}, "B_iv": {"answer": "Yes", "remarks": "Membership terms clause 7.2 allow sharing with appointed processors; the vendor signed a data processing agreement (DPA-2026-014, dummy)."}, "B_v": {"answer": "Yes", "remarks": "Membership consent covers analytics for service improvement; customers who withdrew consent are excluded before extraction."}, "B_vi": {"answer": "Yes", "remarks": "Vendor works inside the BU analytics workspace (no download), 4 named vendor accounts, access ends 2027-03-31."}, "C_i_1": {"answer": "No", "remarks": "Retail sector: no sector-specific restriction on sharing pseudonymised behaviour data with a processor."}, "C_i_2": {"answer": "No", "remarks": "UU PDP: legal basis (consent/legitimate interest), processor agreement, pseudonymisation and DPIA in place."}, "C_i_3": {"answer": "No", "remarks": "Follows the Group Data Sharing Policy: DSR approval, DPIA, RBAC and extermination (BAPD) at project end."}, "D_i": {"answer": "Yes", "remarks": "The vendor trains a gradient-boosting churn model on the features; the AI Checklist (AICK) is completed and a fairness review is done before go-live."}, "ai_assessment": {"items": {"before_use_1": {"status": "Yes", "remarks": "Team completed the Group Gen AI policy training (Sep 2026); use case reviewed against UU PDP and the Group AI Guideline; DPIA completed."}, "before_use_2": {"status": "Yes", "remarks": "llama3.2 runs on the company''s own Ollama server (open licence, approved by IT, 2026-09-25); GitHub Copilot Business licensed under the Group enterprise agreement"}, "before_use_3": {"status": "Yes", "remarks": "Local llama3.2 keeps no chat history and sends nothing outside the company; Copilot Business: prompt/code retention and training use disabled at organisation level."}, "input_1": {"status": "Yes", "remarks": "Prompts contain only column names, data types and masked sample values; no names, NIK, e-mails or phone numbers."}, "input_2": {"status": "Yes", "remarks": "Exploration uses pseudonymised features (hashed customer_id) and the dummy test files TEST01\u2013TEST03."}, "input_3": {"status": "Yes", "remarks": "Prompt templates are stored in the repository and reviewed by the DGO; no customer-group labels used."}, "output_1": {"status": "Yes", "remarks": "Every AI-generated definition and DQ rule is reviewed by the Metadata Officer / DQ Officer before approval; the DQ regex is scored against the real data."}, "output_2": {"status": "Yes", "remarks": "Copilot suggestions go through pull-request review by a senior engineer, unit tests and a security scan before merging."}, "utilization_1": {"status": "Yes", "remarks": "Metadata and DQ results pass the approval workflow (DGO / Data Owner) before publication; model results go to the CRM team after the fairness review."}, "utilization_2": {"status": "Yes", "remarks": "Rejected definitions and rules are regenerated or corrected by hand; outputs are labelled \"need review\" until approved."}}, "sign_off": {"prepared_by": "Ahmad Fauzi", "prepared_position": "Delivery Manager", "acknowledged_by": "Dewi Rahayu", "acknowledged_position": "Head of Business Analytics", "approved": "Yes"}}}','submitted',NULL,NULL);
