INSERT INTO "data_sharing_requests" VALUES('4a6f596cdcef437cbfa1c777e0db5e6c','DSR-2026-0001','5288642d13e845b38f77bcbff82a42c5','458d255ea9f04ad5bed64bbb31fe9cc0','Customer Transaction Dataset Q1-2026','PT Maju Bersama Digital','To train and validate AI-powered analytics models using customer transaction data for personalised financial insight generation, customer behaviour segmentation, and predictive modelling in support of the AI-Powered Customer Analytics Platform initiative.',1,'2026-02-01','2026-12-31',NULL,'approved','2026-01-10 09:00:00','2026-01-25 11:45:00');
INSERT INTO "data_sharing_requests" VALUES('5f8cf7466035447a9cfa3694bd423aaa','DSR-2026-0002','40eaa9f88584426eb9abfc5fc2c9cd19','bf6b981adccb4e6ca4a86f6f14810158','Customer Credit Data','PT Finansial Nusantara','To develop and train a credit risk scoring model leveraging customer transaction history, financial behaviour patterns, and credit bureau data, aimed at improving loan approval accuracy and reducing default rates for PT Finansial Nusantara''s retail banking portfolio under the Smart Credit Risk Analytics Platform initiative.',1,'2026-03-01','2026-12-31',NULL,'under_review','2026-05-07 03:02:08.540473','2026-05-07 03:02:08.540473');
INSERT INTO "data_sharing_requests" VALUES('062b7358ccfe4b4ebbc603c7f4a92c9f','DSR-2026-0003','0f5c16e1aa7d430a97ff34d9bb57b5b7','d37a17105d9f4f8fb3a3b2510317b7d6','DMS After Sales & Service Integration Dataset','Astra UD Trucks','Data sharing is required to support enterprise reporting, operational monitoring, and centralized analytics initiatives across after sales and service operations. The dataset will be used for integration into the corporate analytics platform to improve service performance visibility, billing reconciliation, inventory monitoring, and customer service reporting consistency across dealer networks.',1,'2026-03-03','2026-10-28',NULL,'submitted','2026-05-19 03:18:36.664868','2026-05-19 03:22:02.684664');
INSERT INTO "data_sharing_requests" VALUES('724230d437c04791a8982cdda92c1f8a','DSR-2026-0004','ad670b81df3b4fc0898cb64b3098a186','d37a17105d9f4f8fb3a3b2510317b7d6','Customer 360 Integrated Analytics Dataset','Astra International – Digital Transformation Division','Data sharing is required to support the development of a Customer 360 analytics platform that integrates customer data from multiple sources, including sales transactions, after-sales services, and digital interaction channels. The dataset will be used to enable AI/ML-driven use cases such as customer segmentation, behavior prediction, and personalized recommendations to enhance customer engagement and business decision-making. All data processing will be conducted within a secure environment with appropriate safeguards, including pseudonymization, access control, and compliance with applicable data protection regulations.',1,'2026-02-15','2026-11-30',NULL,'draft','2026-05-20 07:45:26.039319','2026-05-20 07:45:26.039319');
INSERT INTO "data_sharing_requests" VALUES('f3969df6dc194bc5812177071ec8d76e','DSR-2026-0007','fbc7a30750614f68b6d760ac0647fa60','d37a17105d9f4f8fb3a3b2510317b7d6','Churn Features (Pseudonymised)','PT Nusantara Retail Digital','Share the pseudonymised churn features with the data-science vendor to train the churn model. Legal basis: legitimate interest and customer consent. No direct identifiers, named vendor team only, deleted at project end.',1,'2026-10-05','2027-03-31',NULL,'submitted','2026-09-27 08:04:41','2026-09-27 08:50:41');
