INSERT INTO "dpia_records" VALUES('c19f5d23f98146a89bb4c4e9e75056e9','DPIA-2026-0002','40eaa9f88584426eb9abfc5fc2c9cd19','Smart Credit Risk Analytics Platform','','Full Name, Passport Number, Date of Birth, Gender, Email Address, Phone Number, Postal Code, Home / Residential Address, Employee ID, Job Title & Position, IP Address & Device ID','Unauthorised access to customer personal data during AI model training may result in identity theft or financial harm.','Data is pseudonymised before transfer. Access is limited to authorised team members via RBAC. All activity is logged and auditable.','Low',NULL,NULL,NULL,'2026-05-15','d37a17105d9f4f8fb3a3b2510317b7d6','submitted',1,'{"access": [{"id": "access_1", "item": "Data Sharing Request Document", "status": "no", "remarks": "Doesnt need data sharing request", "responsible": "Internal"}, {"id": "access_2", "item": "Revoke / Extermination Documentation", "status": "yes", "remarks": "need to delete all the document related to project deliverable from the ADI environment", "responsible": "Internal"}, {"id": "access_3", "item": "Data Activity Records Documentation (during project)", "status": "yes", "remarks": "Activity logs maintained in centralised audit trail system throughout the project lifecycle.", "responsible": "Internal"}, {"id": "access_4", "item": "Role-Based Access Control Document", "status": "yes", "remarks": "RBAC policy document prepared and approved by DGO. Access limited to 4 authorised team members.", "responsible": "Internal"}, {"id": "access_5", "item": "Assess and Approve Documentation Above", "status": "yes", "remarks": "PT Finansial Nusantara data governance team reviewed and approved all access documentation on 15 Mar 2026.", "responsible": "Client"}, {"id": "access_6", "item": "Grant Access to Project Team Only (per RBAC document)", "status": "yes", "remarks": "Access credentials provisioned for approved team members only via secure VPN tunnel.", "responsible": "Client"}], "secure_data": [{"id": "secure_data_1", "item": "Prepare Mitigated Personal Data (e.g. encrypted, hashed, pseudonymised)", "status": "yes", "remarks": "Customer PII fields pseudonymised using SHA-256 hashing prior to transfer. Data encrypted at rest using AES-256.", "responsible": "Client"}], "data_definition": [{"id": "data_def_1", "item": "Create Metadata Documentation", "status": "yes", "remarks": "Metadata catalogue created covering 11 data attributes across identity, contact, employment, and digital behaviour categories.", "responsible": "Internal"}, {"id": "data_def_2", "item": "Measure Data Quality Index", "status": "yes", "remarks": "DQI measured at 94.2% completeness and 98.7% accuracy across the training dataset. Results reviewed by DQ Officer.", "responsible": "Internal"}, {"id": "data_def_3", "item": "Assess and Approve Metadata Definition", "status": "yes", "remarks": "PT Finansial Nusantara data team reviewed and approved all metadata definitions on 20 Mar 2026.", "responsible": "Client"}, {"id": "data_def_4", "item": "Assess and Approve Data Quality Measurement Approach and Index", "status": "yes", "remarks": "DQ measurement methodology and index approved by PT Finansial Nusantara on 22 Mar 2026.", "responsible": "Client"}], "secure_sharing_environment": [{"id": "secure_env_1", "item": "Provide Secure Environment or Schema to Enable Data Sharing", "status": "yes", "remarks": "Dedicated Supabase schema provisioned with row-level security enabled. Access restricted to whitelisted IP ranges only.", "responsible": "Client"}]}','d37a17105d9f4f8fb3a3b2510317b7d6','2026-05-15 05:32:44.458131','2026-05-15 08:12:06.055609');
