INSERT INTO "dpia_records" VALUES('01585cf632d747c8aaa064f46c60d6b2','DPIA-2026-0003','0f5c16e1aa7d430a97ff34d9bb57b5b7','Enterprise Data Integration Platform Implementation','','Full Name, Email Address, Phone Number','Unauthorized access to customer personal data during AI processing or analytics may lead to data leakage, identity theft, or financial impact.','Data is pseudonymized before processing. Access is restricted through RBAC. All activities are logged and monitored. AI usage is limited to internal analytics within secured environments compliant with data protection regulations.','Low',NULL,NULL,NULL,'2026-05-19','d37a17105d9f4f8fb3a3b2510317b7d6','submitted',1,'{"access": [{"id": "access_1", "item": "Data Sharing Request Document", "status": "yes", "remarks": "Data sharing request has been formally documented, including purpose, scope, and data classification", "responsible": "Internal"}, {"id": "access_2", "item": "Revoke / Extermination Documentation", "status": "yes", "remarks": "Data retention and deletion policy defined; data will be deleted after project end date", "responsible": "Internal"}, {"id": "access_3", "item": "Data Activity Records Documentation (during project)", "status": "yes", "remarks": "Data retention and deletion policy defined; data will be deleted after project end date", "responsible": "Internal"}, {"id": "access_4", "item": "Role-Based Access Control Document", "status": "yes", "remarks": "All data processing activities are logged and auditable within secure environments", "responsible": "Internal"}, {"id": "access_5", "item": "Assess and Approve Documentation Above", "status": "yes", "remarks": "RBAC model is implemented and documented; access restricted to authorized personnel only", "responsible": "Client"}, {"id": "access_6", "item": "Grant Access to Project Team Only (per RBAC document)", "status": "yes", "remarks": "All documentation has been reviewed and approved by data governance and compliance team", "responsible": "Client"}], "secure_data": [{"id": "secure_data_1", "item": "Prepare Mitigated Personal Data (e.g. encrypted, hashed, pseudonymised)", "status": "yes", "remarks": "Personal data is pseudonymized and masked before usage in AI and analytics processes", "responsible": "Client"}], "data_definition": [{"id": "data_def_1", "item": "Create Metadata Documentation", "status": "yes", "remarks": "Metadata documentation has been created for dataset structure, fields, and data lineage", "responsible": "Internal"}, {"id": "data_def_2", "item": "Measure Data Quality Index", "status": "yes", "remarks": "Data quality metrics (completeness, consistency, accuracy) are defined and monitored", "responsible": "Internal"}, {"id": "data_def_3", "item": "Assess and Approve Metadata Definition", "status": "yes", "remarks": "Metadata reviewed and approved by data governance team", "responsible": "Client"}, {"id": "data_def_4", "item": "Assess and Approve Data Quality Measurement Approach and Index", "status": "yes", "remarks": "Data quality framework validated and aligned with enterprise standards", "responsible": "Client"}], "secure_sharing_environment": [{"id": "secure_env_1", "item": "Provide Secure Environment or Schema to Enable Data Sharing", "status": "yes", "remarks": "Data sharing is conducted within secure enterprise environment with encryption, access control, and monitoring", "responsible": "Client"}]}','d37a17105d9f4f8fb3a3b2510317b7d6','2026-05-19 03:18:36.664868','2026-05-19 03:30:46.679624');
