INSERT INTO "dpia_records" VALUES('1c3aaf2d9f084e7a9ccd61f2c32fe211','DPIA-2026-0007','fbc7a30750614f68b6d760ac0647fa60','Retail Customer Churn Prediction','','Full Name, National ID / IC Number, Date of Birth, Gender, Email Address, Phone Number, Transaction History, Online Purchase Behaviour, Customer Relationship (CRM)','ML profiling combines identity, contact and purchase data. Risks: re-identification if data leaks, unfair targeting, and use of contact data beyond the consent.','Pseudonymise identifiers; RBAC for the project team only; vendor gets features only; fairness review before go-live; offers only to opted-in customers; delete data at project end.','Medium',NULL,NULL,NULL,'2026-09-27','d37a17105d9f4f8fb3a3b2510317b7d6','submitted',1,'{"access": [{"id": "access_1", "item": "Data Sharing Request Document", "responsible": "Internal", "status": "yes", "remarks": "DSR-2026-0007 (churn features to the vendor, AI use) submitted in the platform; DSR 2 (transactions to the auditor) follows."}, {"id": "access_2", "item": "Revoke / Extermination Documentation", "responsible": "Internal", "status": "yes", "remarks": "BAPD extermination request planned at access end (2027-03-31 vendor, 2026-11-30 auditor); proof of deletion kept in the platform."}, {"id": "access_3", "item": "Data Activity Records Documentation (during project)", "responsible": "Internal", "status": "yes", "remarks": "Every access and change is logged in the platform audit log; monthly access review by the DGO (Anisa Putri)."}, {"id": "access_4", "item": "Role-Based Access Control Document", "responsible": "Internal", "status": "yes", "remarks": "\tRBAC matrix v1.0 (2026-10-01): 4 named vendor accounts (read-only features), 2 named auditors, project team per role."}, {"id": "access_5", "item": "Assess and Approve Documentation Above", "responsible": "Client", "status": "yes", "remarks": "Reviewed and approved by Sri Handayani (CRM Department Head) on 2026-10-02."}, {"id": "access_6", "item": "Grant Access to Project Team Only (per RBAC document)", "responsible": "Client", "status": "yes", "remarks": "Access granted by the client IT team per RBAC v1.0 on 2026-10-05; access list reviewed monthly."}], "secure_data": [{"id": "secure_data_1", "item": "Prepare Mitigated Personal Data (e.g. encrypted, hashed, pseudonymised)", "responsible": "Client", "status": "yes", "remarks": "customer_id hashed (SHA-256 with a secret salt held by the client); name, NIK, e-mail, phone and birth date removed from the shared files."}], "secure_sharing_environment": [{"id": "secure_env_1", "item": "Provide Secure Environment or Schema to Enable Data Sharing", "responsible": "Client", "status": "yes", "remarks": "Dedicated analytics workspace (schema churn_prj022) with no download, MFA login and encryption at rest; separate read-only share for the auditor."}], "data_definition": [{"id": "data_def_1", "item": "Create Metadata Documentation", "responsible": "Internal", "status": "yes", "remarks": "Metadata for the 3 tables (30 attributes) generated and reviewed in Metadata Management; personal-data columns flagged."}, {"id": "data_def_2", "item": "Measure Data Quality Index", "responsible": "Internal", "status": "yes", "remarks": "DQ run on all 3 files; Project DQ Report shared: 2 blank attributes (legacy_fax, analyst_notes) and stale last_visit_date flagged for follow-up."}, {"id": "data_def_3", "item": "Assess and Approve Metadata Definition", "responsible": "Client", "status": "yes", "remarks": "Metadata definitions reviewed by Rizky Pramono (Lead Business Steward); approval planned for 2026-10-09."}, {"id": "data_def_4", "item": "Assess and Approve Data Quality Measurement Approach and Index", "responsible": "Client", "status": "yes", "remarks": "DQ method (4 dimensions, llama3.2 rules) and index reviewed with the Data Owner; approval planned for 2026-10-09."}]}','d37a17105d9f4f8fb3a3b2510317b7d6','2026-09-27 08:04:41','2026-09-27 09:33:18');
