INSERT INTO "metadata_records" VALUES('bfdc069d81b34c1da7487c89ae882f18','5288642d13e845b38f77bcbff82a42c5',76,'','customer_data.xlsx - Sheet1',NULL,'Source','AI-Powered Customer Analytics Platform',2026,'','','phone_number',NULL,'Highly Confidential','Customer','Phone Number','Captures and records a unique identifier for individual customers within the customer domain, specifically tied to their personal contact information. Used in business decisions such as account management, marketing campaigns, and customer service interactions to track and identify specific individuals, with highly confidential data handled under our data privacy policy.','ai_generated','Phone number',1,1,'798.035.1886x82894 | +62 (043) 748-1535 | 697.293.1083x720 | +62 (141) 095 5631 | (858)808-4666','STRING','Raw','2026-05-25','Super Administrator <admin@governance.local>','-','excel',1500,NULL,'2026-05-18 09:20:40.027151');
INSERT INTO "metadata_records" VALUES('64cec6b4ea7b478fbb6ef73ea20251d3','5288642d13e845b38f77bcbff82a42c5',80,'','customer_data.xlsx - Sheet1',NULL,'Source','AI-Powered Customer Analytics Platform',2026,'','','address',NULL,'Highly Confidential','Customer','Address','Captures and records highly confidential information about a customer''s physical location, which is used to facilitate secure delivery of goods or services and inform targeted marketing efforts. It plays a critical role in business decisions by enabling organizations to tailor their offerings and interactions with customers based on their specific addresses. This data is handled under our company''s personal identifiable information policy and uniquely identifies each record due to its unique combination of characters, making it an essential component of customer profiles.','ai_generated','Free text (long description)',1,0,'Jalan Dipenogoro No. 83, Cimahi, Sulawesi Tenggara 04087 | Gang Veteran No. 538, Salatiga, NB 14822 | 6081 Shane Extensions Suite 687, Caseystad, CA 87261 | Gg. KH Amin Jasuta No. 29, Lubuklinggau, Jawa Tengah 92959 | Gang M.H Thamrin No. 946, Palembang, SU 50425','STRING','Raw','2026-05-25','Super Administrator <admin@governance.local>','-','excel',1500,NULL,'2026-05-18 09:20:40.027151');
