INSERT INTO "projects" VALUES('85eaf07b22984658baaaa5e267c74812','PRJ-2026-003','PT ABC Tbk','Banking','Enterprise Data Governance Implementation','Implementation of an enterprise data governance framework to improve data consistency, ownership, metadata management, and regulatory compliance across business domains. The project includes data cataloging, business glossary standardization, data quality monitoring, and governance workflow enablement to support reliable and trusted enterprise data usage.',2026,'Data Governance',1,'2026-05-01','2026-10-31','3991d4dddeb4432c9a8aedee818513b0','eb2cf472bae34648b444ac549055b410','2c8b080e236f4808ba5024c9f6a3c494','458d255ea9f04ad5bed64bbb31fe9cc0','5b5a78847ea44fbcb7dd0c9d44567ab1','ac6a037060964450a5a923c9a534e6b9','c42140f876ff4c9cbbe3a741ca63e3fa','d37a17105d9f4f8fb3a3b2510317b7d6','2026-05-13 02:54:35.239403','2026-05-13 06:10:42.310928');
INSERT INTO "projects" VALUES('0f5c16e1aa7d430a97ff34d9bb57b5b7','PRJ-2026-018','Astra UD Trucks','Automotive Distribution & After Sales','Enterprise Data Integration Platform Implementation','Implementation of enterprise data integration solution to consolidate operational data from Dealer Management System (DMS), after sales, inventory, billing, and customer service applications into centralized reporting and analytics platforms. The project includes ETL pipeline development, API integration, data mapping standardization, and automated data synchronization processes.',2026,'Integration',1,'2026-03-03','2026-10-28','4a1a48b455b24ed484a8ae84851e870d','89efb71cc9f142248fa5ae4b5e211402','eb2cf472bae34648b444ac549055b410','8216e50cc627469da6961e91285f5aab','4908c50c2a1d4ab58a1c68965e49ba47','4908c50c2a1d4ab58a1c68965e49ba47','336b54209af049deb844e42ee6658cd4','d37a17105d9f4f8fb3a3b2510317b7d6','2026-05-19 03:17:28.948382','2026-05-19 03:17:28.948382');
INSERT INTO "projects" VALUES('ad670b81df3b4fc0898cb64b3098a186','PRJ-2026-004','Astra International – Digital Transformation Division','Retail & Automotive Ecosystem','Customer 360 Analytics and Personalization Platform','Develop a Customer 360 platform that integrates data from multiple sources, including sales, after-sales, and customer interaction systems, into a unified analytics environment. The solution leverages AI/ML models to generate insights such as customer segmentation, behavior prediction, and personalized recommendations to support business decision-making. All data processing is conducted within a secure and governed environment, with appropriate controls such as pseudonymization, access restriction, and compliance with applicable data protection regulations.',2026,'AI / ML',1,'2026-02-15','2026-11-30','4a1a48b455b24ed484a8ae84851e870d','89efb71cc9f142248fa5ae4b5e211402','eb2cf472bae34648b444ac549055b410','8216e50cc627469da6961e91285f5aab','8216e50cc627469da6961e91285f5aab','8216e50cc627469da6961e91285f5aab','f961edea0a7a4f6c8738098f640b6dc8','d37a17105d9f4f8fb3a3b2510317b7d6','2026-05-20 07:44:22.733017','2026-05-20 07:44:22.733017');
INSERT INTO "projects" VALUES('fbc7a30750614f68b6d760ac0647fa60','PRJ-2026-022','PT Nusantara Retail Digital','Retail & Consumer Analytics','Retail Customer Churn Prediction','Predict which retail customers are likely to stop shopping in the next 90 days, so the CRM team can send retention offers. Personal data is pseudonymised before modelling.',2026,'AI / ML',1,'2026-10-01','2027-03-31','92d40357c37041bd843ca09f0abc31a6','eb2cf472bae34648b444ac549055b410','458d255ea9f04ad5bed64bbb31fe9cc0','2c8b080e236f4808ba5024c9f6a3c494','4c6b086280a3471ab21f57091048947f','cb8ec3d213ba41bc9c06bac73ad0d7b8','5b5a78847ea44fbcb7dd0c9d44567ab1','d37a17105d9f4f8fb3a3b2510317b7d6','2026-09-27 08:03:20','2026-09-27 08:36:48');
